'use strict';
const M=window.PauseModel;let state=M.create();const main=document.querySelector('#main');const privacy=document.querySelector('#privacy');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const feelingLabels={'switch-off':'Tired',interest:'Bored',company:'Want company',distance:'Overwhelmed',unsure:'Not sure'};
function dispatch(type,value,extra={}){state=M.transition(state,{type,value,...extra});render();}
function render(focus=true){
 document.querySelector('.progress').hidden=state.view==='off';
 document.querySelector('#stop').hidden=state.view==='off';
 document.querySelectorAll('[data-step]').forEach(el=>{if(el.dataset.step===state.view)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});
 if(state.view==='choose')main.innerHTML=`<h1>Choose your break.</h1><p class="intro">Pick something that fits what you need right now.</p><form id="choose-form"><fieldset class="field"><legend>How are you feeling? <span class="optional">Optional</span></legend><div class="needs">${M.needs.map(n=>`<label class="need"><input type="radio" name="need" value="${n.id}" id="need-${n.id}" ${state.need===n.id?'checked':''}><span>${feelingLabels[n.id]}</span></label>`).join('')}</div></fieldset><fieldset class="field"><legend>What would you like to do?</legend><div class="break-list">${M.getOptions(state).map(o=>`<label class="break-option"><input type="radio" name="activity" value="${o.id}" id="activity-${o.id}" ${state.selected?.id===o.id?'checked':''} required><span><span class="break-title">${esc(o.title)}</span><span class="break-description">${esc(o.description)}</span></span></label>`).join('')}</div>${state.selected?.id==='own'?`<div class="custom-field"><label for="custom">My idea</label><input id="custom" type="text" maxlength="160" placeholder="Call a friend, sit outside…" value="${esc(state.custom)}" required></div>`:''}</fieldset><div class="start-row"><button class="primary" type="submit" ${state.selected?'':'disabled'}>Start my break</button><p>${state.selected?'No timer. Come back when you want.':'Choose a break above to start.'}</p></div></form><button class="text-button already" data-action="already">I’m already on a break. Choose what’s next.</button>`;
 if(state.view==='rest'){const a=state.selected;main.innerHTML=`<h1>Take your break.</h1><p class="intro">You can leave this screen now.</p><section class="rest-content"><p class="rest-label">YOU CHOSE</p><h2>${esc(state.custom||a.title)}</h2><p class="instruction">${esc(a.instruction)}</p>${a.cue?`<div class="cue"><span>A possible moment to check in — only if it helps</span><p>${esc(a.cue)}.</p></div>`:''}<p class="note">Nothing will pop up or stop you. When you want to decide what’s next, come back here.</p></section><div class="actions"><button class="primary" data-action="return">I’m back</button><button class="text-button" data-action="change">Choose a different break</button></div>`;}
 if(state.view==='next'){
 const decisions={study:['Back to studying.','You chose to return to study. You can close this page and carry on when you’re ready.'],plan:['Go with a different plan.','You chose to do something else. There’s no need to write it down or explain it here.'],finish:['Finished for now.','You chose to stop studying. You can close this page.']};
 const result=state.decision?decisions[state.decision]:null;
 main.innerHTML=`<h1>What would you like to do next?</h1><p class="intro">You don’t have to go straight back to studying.</p>${result?`<section class="result" role="status"><h2>${result[0]}</h2><p>${result[1]}</p></section><div class="result-actions"><button class="secondary" data-action="reconsider">Choose something else</button><button class="text-button" data-action="reset">Start a new break</button></div>`:`<div class="next-list"><button class="next-choice" data-action="continue"><span>${state.selected?.id==='scroll'?'Keep scrolling':'Keep resting'}</span><span>Take more time</span></button><button class="next-choice" data-action="change"><span>Try a different break</span><span>Choose again</span></button><button class="next-choice" data-action="decide" data-value="study"><span>Go back to studying</span></button><button class="next-choice" data-action="decide" data-value="plan"><span>Change my study plan</span></button><button class="next-choice" data-action="decide" data-value="finish"><span>Finish studying for now</span></button></div><details class="reflection"><summary>Reflect on the break <span class="optional">Optional</span></summary><div class="reflection-options" role="group" aria-label="How the break felt">${[['helped','It helped'],['same','About the same'],['more','I need more rest']].map(([v,t])=>`<label><input type="radio" name="feedback" value="${v}" ${state.feedback===v?'checked':''}>${t}</label>`).join('')}</div></details>`}`;
 }
 if(state.view==='off')main.innerHTML='<h1>Pause is off.</h1><p class="intro">You can close this page. There are no reminders or tracking running.</p><div class="actions"><button class="secondary" data-action="reset">Use Pause again</button></div>';
 if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
}
main.addEventListener('change',event=>{const el=event.target;if(el.name==='need'||el.name==='activity'){state=M.transition(state,{type:el.name==='need'?'NEED':'SELECT',value:el.value});render(false);document.getElementById(el.id)?.focus({preventScroll:true});}if(el.name==='feedback')state=M.transition(state,{type:'FEEDBACK',value:el.value});});
main.addEventListener('input',event=>{if(event.target.id==='custom')state={...state,custom:event.target.value};});
main.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='choose-form')dispatch('START',undefined,{custom:document.querySelector('#custom')?.value||''});});
main.addEventListener('click',event=>{const b=event.target.closest('button[data-action]');if(!b)return;const actions={already:'ALREADY',return:'RETURN',change:'CHANGE',continue:'CONTINUE',decide:'DECIDE',reset:'RESET'};if(b.dataset.action==='reconsider'){state={...state,decision:null};render();}else if(actions[b.dataset.action])dispatch(actions[b.dataset.action],b.dataset.value);});
document.querySelector('#stop').addEventListener('click',()=>dispatch('OFF'));
document.querySelector('#privacy-open').addEventListener('click',()=>privacy.showModal());document.querySelector('#privacy-close').addEventListener('click',()=>privacy.close());render(false);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_break_state',description:'Read which of the three break steps is visible, the chosen need and activity, and the next-step decision. Does not change the break.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({step:state.view,need:state.need,activity:state.selected?.id||null,decision:state.decision,supportEnabled:state.enabled})})).catch(()=>{});}catch{}}
